"""Offline inspection of pinned existing evidence; no producer execution or data collection."""
import collections,hashlib,json,math,statistics,subprocess
from pathlib import Path
P=Path(__file__).parent; c=json.loads((P/'CONTRACT.json').read_text());ref=c['sourceRef']
raw={p:subprocess.check_output(['git','show',ref+':'+p]) for p in c['pins']}
for p,b in raw.items():
 if hashlib.sha256(b).hexdigest()!=c['pins'][p]:raise ValueError('input changed: '+p)
j=json.loads(raw['data/research-lab.json']);rows=j['trades'][c['primary']];net=[r['net'] for r in rows];N=len(rows)
def stats(a):return {'n':len(a),'mean':statistics.mean(a) if a else None,'median':statistics.median(a) if a else None,'losses':sum(x<0 for x in a),'worst':min(a) if a else None,'best':max(a) if a else None}
first=j['firstRun'][c['primary']];latest=j['latest']['results'][c['primary']]
controls={k:stats([r['net']-r[k] for r in rows if isinstance(r.get(k),(int,float))]) for k in ['avgStock','sameStock']}
dates=sorted({r[k] for r in rows for k in ['buy','sell']});overlap=max((sum(r['buy']<=d<=r['sell'] for r in rows),d) for d in dates)
required=['entryPrice','exitPrice','entryBid','entryAsk','quoteTimestamp','accession','acceptedAt','originalFactBytesHash','corporateActionBasis','ZADAtEntry']
report={'contractCommit':'3753afa0a','sourceRef':ref,'inputSha256':c['pins'],'originalFirstRun':first,'laterMonitoring':latest,'retainedRows':N,'retainedOnlyNotFullTrial':True,'retainedDateRange':{'signal':[min(r['sig'] for r in rows),max(r['sig'] for r in rows)],'buy':[min(r['buy'] for r in rows),max(r['buy'] for r in rows)]},'retainedModeledNet':stats(net),'allRetainedFixedOriginalStress1_2Percent':stats([x-.004 for x in net]),'retainedWithoutTwoBestDiagnosticNotFilter':stats(sorted(net)[:-2]),'retainedPairedNetMinusSavedControl':controls,'retainedSymbolCounts':dict(collections.Counter(r['s'] for r in rows).most_common()),'retainedSignalDateCounts':dict(sorted(collections.Counter(r['sig'] for r in rows).items())),'retainedConcurrentCommittedPositions':{'maximum':overlap[0],'date':overlap[1],'endpointConvention':'buy<=date<=sell, before same-day exit; retained subset only','referenceCapitalIfEverySignalAllocated1000':overlap[0]*1000,'notAPortfolioBacktest':True},'missingFieldsCounts':{k:sum(k not in r or r[k] is None for r in rows) for k in required},'rowsWithPlausibleRuleClocks':sum(r['sig']<r['buy']<r['sell'] for r in rows),'duplicatesExact':N-len({json.dumps(r,sort_keys=True) for r in rows}),'notes':['Producer saves only trades.slice(-400); this tail cannot reproduce original full trial, chronological holdout or full-universe verdict.','pct is backlog percentile, NOT gross price return.','Saved controls do not include entry/exit dollar prices, raw execution or quote lineage; cost comparability requires producer inspection.','Date ordering does not authenticate original publication/acceptance or original financial vintages.','One open trade per ticker per rule does not constrain total portfolio capital across tickers.','No current-reference identity, ZAD, halt/no-fill, corporate-action or point-in-time membership is inferred.','Fixed original stress is a modeled arithmetic sensitivity, not measured execution cost.','No drawdown or whole-share profit is invented without entry/exit prices and paths.'],'terminal':'STOP promotion of unchanged rejected RPO63; exact executable economics INCONCLUSIVE; no new variant or collection authorized.'}
(P/'RESULTS.json').write_text(json.dumps(report,indent=2)+'\n')
print(json.dumps({k:report[k] for k in ['retainedRows','retainedDateRange','retainedModeledNet','allRetainedFixedOriginalStress1_2Percent','retainedWithoutTwoBestDiagnosticNotFilter','retainedPairedNetMinusSavedControl','retainedConcurrentCommittedPositions','missingFieldsCounts','terminal']},indent=2))
